def finiteLift (F : Finset P) (c : P → 𝕜) (j : ∀ p, Z →L[𝕜] X p) :
    Z →L[𝕜] DependentCZeroSum 𝕜 X :=
  ∑ p ∈ F, c p • (sumInjection 𝕜 X p).comp (j p)

